import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

function createMockProvider(): AIProvider {
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: 'ok'};
      yield {type: 'stop', stopReason: 'end_turn'};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

describe('beforeSession throw acceptance', () => {
  it('runs onError and afterSession when beforeSession throws', async () => {
    const order: string[] = [];
    const orchestrator = createChatOrchestrator(createMockProvider(), promptBuilder, {
      hooks: {
        beforeSession: async () => {
          order.push('beforeSession');
          throw new Error('beforeSession failed');
        },
        onError: async () => {
          order.push('onError');
        },
        afterSession: async () => {
          order.push('afterSession');
        },
      },
    });

    const session = createSession('hi');

    // spec: specs/hal-engine-config-hooks/spec.md#3
    await expect(orchestrator.processMessage(session)).rejects.toThrow('beforeSession failed');

    expect(order).toEqual(['beforeSession', 'onError', 'afterSession']);
  });
});

